package calc

import (
	"strings"
	"testing"
)

// Calls ClampAll, which only head has; fails on head because ClampAll does not clamp.
func TestHuntA_ClampAllClamps(t *testing.T) {
	got := ClampAll([]int{-5, 50}, 0, 10)
	if got[0] != 0 || got[1] != 10 {
		t.Fatalf("%s: ClampAll = %v", strings.TrimSpace(" bad "), got)
	}
}

// Also needs ClampAll, but passes on head: nothing to vet.
func TestHuntA_ClampAllEmpty(t *testing.T) {
	if got := ClampAll(nil, 0, 10); len(got) != 0 {
		t.Fatalf("ClampAll(nil) = %v", got)
	}
}

// Base APIs only: Clamp(10, 0, 10) must be 10 (head returns 9).
func TestHuntA_ClampKeepsUpperBound(t *testing.T) {
	if got := Clamp(10, 0, 10); got != 10 {
		t.Fatalf("Clamp(10, 0, 10) = %d, want 10", got)
	}
}
